import json, os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = "Fingers of the Eldest: The Bogatyri (Storytellers Vault)"
TAG = {"era": "bogatyr", "fan": True, "source": SRC}


def load(name):
    with open(os.path.join(ROOT, "data", name), encoding="utf-8") as f:
        return json.load(f)


def save(name, data):
    with open(os.path.join(ROOT, "data", name), "w", encoding="utf-8", newline="") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
        f.write("\n")


def sec(desc, system):
    return f'<h4 class="r-sec">Описание</h4>\n{desc}\n<h4 class="r-sec">Система</h4>\n{system}'


